internal enum class BrowserTopNoticeKind { FULLSCREEN, DOWNLOAD, TAB_CLOSED }

internal data class BrowserTopNotice(
    val id: Long,
    val kind: BrowserTopNoticeKind,
    val title: String,
    val message: String,
    val actionLabel: String? = null
)

